package io.lumine.mythic.lib.script.variable;import java.util.function.Function;public final class SimpleVariableRegistry<T extends Variable<?>> implements VariableRegistry<T>{private final Function<T,String> stringifier;public SimpleVariableRegistry(){this(Object::toString);}public SimpleVariableRegistry(Function<T,String> stringifier){this.stringifier=stringifier;}public Variable<?> get(T variable,String path){return path==null||path.isBlank()?variable:null;}public String stringify(T variable){return stringifier.apply(variable);}}